const promptText = $input.first().json.choices[0].message.content;
// Remove markdown code blocks if present
const cleanPrompt = promptText.replace(/`/g, '').trim();
const seed = Math.floor(Math.random() * 1000000000000000);

const comfyReq = {
  "3": {
    "inputs": {
      "seed": seed,
      "steps": 4,
      "cfg": 1,
      "sampler_name": "euler",
      "scheduler": "simple",
      "denoise": 1,
      "model": ["4", 0],
      "positive": ["6", 0],
      "negative": ["7", 0],
      "latent_image": ["5", 0]
    },
    "class_type": "KSampler"
  },
  "4": {
    "inputs": {
      "ckpt_name": "flux1-schnell.safetensors"
    },
    "class_type": "CheckpointLoaderSimple"
  },
  "5": {
    "inputs": {
      "width": 1024,
      "height": 1024,
      "batch_size": 1
    },
    "class_type": "EmptyLatentImage"
  },
  "6": {
    "inputs": {
      "text": cleanPrompt,
      "clip": ["4", 1]
    },
    "class_type": "CLIPTextEncode"
  },
  "7": {
    "inputs": {
      "text": "text, watermark",
      "clip": ["4", 1]
    },
    "class_type": "CLIPTextEncode"
  },
  "8": {
    "inputs": {
      "samples": ["3", 0],
      "vae": ["4", 2]
    },
    "class_type": "VAEDecode"
  },
  "9": {
    "inputs": {
      "filename_prefix": "Digest_Cover_" + Date.now(),
      "images": ["8", 0]
    },
    "class_type": "SaveImage"
  }
};

return { json: { comfyReq, cleanPrompt, seed, timestamp: Date.now() } };

const items = $('Aggregate Topics').first().json.items;
const coverImageId = $json.prompt_id;
const prefix = 'Digest_Cover_' + $('Prepare Flux Request').first().json.timestamp;
const imageUrl = `http://192.168.0.9:8188/view?filename=${prefix}_00001_.png`;

if (!items || items.length === 0) return [];

let markdown = "# 🌩️ Broken Cloud News Digest\n\n";
markdown += `![Daily Cover](${imageUrl})\n\n`;

items.forEach(item => {
  markdown += `### [${item.title}](${item.url})\n`;
  markdown += `**Score:** ${item.juiciness_score}/10 | **Source:** ${item.source_type}\n`;
  markdown += `${item.summary}\n\n`;
});

markdown += "---\n*Generated by Broken Cloud News Agent* 🤖";

// We return the items so the calling workflow knows which IDs to update
return { json: { markdown: markdown, count: items.length, ids: items.map(i => i.id) } };
